#!/usr/bin/env bash
# metrics-server/metrics-server 3.13.0 - preset: default
# Path: pull the package, render this preset locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this preset. Chart page: https://confighub.github.io/helm-expt/site/charts/metrics-server-metrics-server-3-13-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install it with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the default preset into ./metrics-server-metrics-server-3-13-0-default"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/metrics-server-metrics-server:3.13.0 --base default --work-dir ./metrics-server-metrics-server-3-13-0-default --non-interactive --namespace kube-system

say "Read what was rendered; nothing has touched the cluster yet"
ls ./metrics-server-metrics-server-3-13-0-default/out/manifests

say "Ensure the kube-system namespace exists"
kubectl create namespace kube-system --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./metrics-server-metrics-server-3-13-0-default/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./metrics-server-metrics-server-3-13-0-default/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./metrics-server-metrics-server-3-13-0-default/out/manifests

say "Done. The cluster received exactly the files in ./metrics-server-metrics-server-3-13-0-default/out."
